  AvgVideoCaption_149926_Content_99 = {
    Text = "ฉันเคยลองแล้ว"
  },
  AvgVideoCaption_18618_Content_1 = {
    Text = "ในห้วงลึกของห้องลับ มอนสเตอร์สีขาวบริสุทธิ์นิ่งเงียบอยู่"
  },
  AvgVideoCaption_18619_Content_1 = {
    Text = "ประกายของความคลั่งค่อยๆ จางหายไปจากดวงตาของโรแทน แทนที่ด้วยสีหม่นที่เปล่งประกายสีเงิน."
  },
  AvgVideoCaption_18619_Content_2 = {
    Text = "โรแทน ที่ฟื้นคืนสติดูเหมือนกำลังทนทุกข์จากอาการปวดหัวอย่างหนัก ยกมือประคองหน้าผากข้างหนึ่งแล้วก้มศีรษะลง"
  },
  AvgVideoCaption_18620_Content_1 = {
    Text = "เมื่อเสียงของเธอเงียบลง ทุกสรรพสิ่งที่เหนือธรรมชาติก็หายไปในพริบตา"
  },
  AvgVideoCaption_18621_Content_1 = {
    Text = "เธอยกมือขึ้น แล้วเช็ดกระจกตรงหน้าจนสะอาด"
  },
  AvgVideoCaption_18622_Content_1 = {
    Text = "แสงทองคำของดวงอาทิตย์ที่กำลังลับขอบฟ้าส่องผ่านหน้าปัดนาฬิกาขนาดใหญ่ที่โปร่งใสของหอระฆัง แล้วสาดลงบนตัวของเด็กสาว"
  },
  AvgVideoCaption_18623_Content_1 = {
    Text = "กลับมาเป็นเหมือนเดิมที่เหลือแค่ตัวเอง"
  },
  AvgVideoCaption_18624_Content_1 = {
    Text = "ในชั่วขณะถัดมา ลักษณะที่แปลกประหลาดก็จางหายไป"
  },
  AvgVideoCaption_18625_Content_1 = {
    Text = "เมื่ออยู่หน้าสิ่งที่ยิ่งใหญ่และไม่รู้จักเหล่านั้น.."
  },
  AvgVideoCaption_18625_Content_10 = {
    Text = "เมื่อได้ยินคำนั้น ความเจ็บปวดและเสียงหึ่งรุนแรงก็พุ่งเข้าสู่สมองอย่างจัง"
  },
  AvgVideoCaption_18625_Content_11 = {
    Text = "ท้องไส้ปั่นป่วน กลิ่นแรงของอาเจียนกระทบจมูก"
  },
  AvgVideoCaption_18625_Content_2 = {
    Text = "มนุษย์นั้นช่างเล็กน้อยเหลือเกิน"
  },
  AvgVideoCaption_18625_Content_3 = {
    Text = "เป็นความฝันหรือเปล่า?"
  },
  AvgVideoCaption_18625_Content_4 = {
