  },
  AvgVideoCaption_18625_Content_5 = {
    Text = "—มหาวิทยาลัยมิซากะ พิธีมอบกุญแจเงิน—"
  },
  AvgVideoCaption_18625_Content_6 = {
    Text = "“...มหาวิทยาลัยมิซากะเป็นผู้นำในการต่อสู้กับ@2...”"
  },
  AvgVideoCaption_18625_Content_7 = {
    Text = "“...กลายเป็นนักสืบของมหาวิทยาลัยมิซากะ”"
  },
  AvgVideoCaption_18625_Content_8 = {
    Text = "“นั่นหมายถึงชีวิตที่เหลือของพวกคุณจะต้องอยู่ร่วมกับความตายและความบ้าคลั่ง...”"
  },
  AvgVideoCaption_18625_Content_9 = {
