  AvgVideoCaption_18626_Content_10 = {
    Text = "ปลายปลายนิ้วรู้สึกชื้น แต่ไร้ซึ่งความรู้สึกสัมผัสจริง"
  },
  AvgVideoCaption_18626_Content_11 = {
    Text = "ความจริงเพียงเล็กน้อยสลายหายไปจากปลายนิ้วของเธอ แล้วจากโลกนี้ไปตลอดกาล."
