  },
  AvgVideoCaption_18626_Content_3 = {
    Text = "จะไม่ทำให้เกิดความเสียหายกับใครอีกแล้ว."
  },
  AvgVideoCaption_18626_Content_4 = {
    Text = "จะไม่ยอมให้เพื่อนตายเพราะฉันอีก"
  },
  AvgVideoCaption_18626_Content_5 = {
    Text = "ด้วยเสียงระฆังช่วยกลบ ไอจิสไม่รู้ใช้วิธีอะไร แต่สามารถเปิดกระจกที่ควรจะปิดตายได้อย่างง่ายดาย"
