  },
  AvgVideoCaption_18626_Content_8 = {
    Text = "ไอจิสปิดตาลง รู้สึกเพียงว่าตัวเองเบาขึ้น เบามาก ในขณะที่ข้างหลังเธอ รามอน่าเอื้อมมือออกอย่างเร่งรีบไปยังท้องฟ้ายามราตรี"
  },
  AvgVideoCaption_18626_Content_9 = {
    Text = "สัมผัสและจับไว้ให้มั่น"
  },
  AvgVideoCaption_22146_Content_1 = {
    Text = "ภัยพิบัติที่น่ากลัวได้การปรากฏตัว"
  },
  AvgVideoCaption_22146_Content_2 = {
    Text = "「การละลายกร่อน」"
