  AvgVideoCaption_22146_Content_8 = {
    Text = "วิญญาณเหล่านี้คือความหวังสุดท้ายของเรา"
  },
  AvgVideoCaption_22146_Content_9 = {
    Text = "อย่างน้อย เราก็คาดหวังเช่นนั้น.."
  },
  AvgVideoCaption_24281_Content_1 = {
    Text = "ในที่สุดก็มาถึงช่วงเวลาของการบาน"
