  AvgVideoCaption_36151_Content_13 = {
    Text = "ทำไมต้องยอมแพ้!"
  },
  AvgVideoCaption_36151_Content_14 = {
    Text = "พลีชีพ! สร้างใหม่สวรรค์——"
  },
  AvgVideoCaption_36151_Content_15 = {
    Text = "สวรรค์อะไร เทพอะไร... แล้วมันเกี่ยวอะไรกับฉัน!"
  },
  AvgVideoCaption_36151_Content_16 = {
    Text = "พลีชีพ! คืนเจ้านายของข้า——"
  },
  AvgVideoCaption_36151_Content_17 = {
    Text = "ออกไปจากที่นี่เถอะ เรา... ออกไปจากที่นี่กัน!"
  },
  AvgVideoCaption_36151_Content_2 = {
    Text = "พระมารดาเทพ ทำไมถึงจากไป?"
  },
  AvgVideoCaption_36151_Content_3 = {
    Text = "อย่า... ฉันไม่ต้องการเป็นแม่แห่งเทพ"
