  AvgVideoCaption_36151_Content_8 = {
    Text = "แล้วก็... ไม่ทันแล้วเหรอ?"
  },
  AvgVideoCaption_36151_Content_9 = {
    Text = "แต่...ทำไมล่ะ!?"
  },
  AvgVideoCaption_45044_Content_1 = {
    Text = "การปรากฏตัวของโรคระบาดที่มองไม่เห็นได้มาถึงแล้ว"
  },
  AvgVideoCaption_45044_Content_10 = {
    Text = "“คุณจะยอมเสียสละเนื้อและเลือดของคุณเพื่อพวกเราหรือไม่?”"
  },
  AvgVideoCaption_45044_Content_11 = {
    Text = "“คุณจะยอมสละชีวิตของคุณเพื่อพวกเราหรือไม่?”"
  },
  AvgVideoCaption_45044_Content_12 = {
    Text = "「พระบิดาทรงหลั่งน้ำตาเพื่อลูกๆ ของพระองค์」"
  },
  AvgVideoCaption_45044_Content_13 = {
    Text = "「พระองค์ทรงประสงค์ให้เราผู้สูงศักดิ์เป็นผู้แทนของพระองค์」"
  },
  AvgVideoCaption_45044_Content_14 = {
    Text = "「ทำให้ความทุกข์หายไปจากแผ่นดินนี้.」"
  },
  AvgVideoCaption_45044_Content_15 = {
    Text = "ข้าคือผู้แทนของเทพผู้เป็นบิดา"
  },
  AvgVideoCaption_45044_Content_16 = {
    Text = "ย่อมต้องทำอย่างสุดความสามารถ"
  },
  AvgVideoCaption_45044_Content_17 = {
    Text = "“ทำไมนะท่านบิชอป ทำไมวันนี้ไม่มีพร?”"
  },
  AvgVideoCaption_45044_Content_18 = {
    Text = "“ทำไมเธอไม่ไปต่อ ทำไมไม่ช่วยเรา!”"
  },
  AvgVideoCaption_45044_Content_19 = {
    Text = "“คุณจะไร้ความสามารถได้อย่างไร?”"
  },
  AvgVideoCaption_45044_Content_2 = {
